import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"32、【恒】 巽下震上","description":"温公易说 - 32、【恒】 巽下震上","frontmatter":{"title":"32、【恒】 巽下震上","description":"温公易说 - 32、【恒】 巽下震上"},"headers":[],"relativePath":"zh/classics/wengong/033.md","filePath":"zh/classics/wengong/033.md"}'),n={name:"zh/classics/wengong/033.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_32、【恒】-巽下震上" tabindex="-1">32、【恒】 巽下震上 <a class="header-anchor" href="#_32、【恒】-巽下震上" aria-label="Permalink to “32、【恒】 巽下震上”">​</a></h1><h3 id="彖曰-恒-久也。刚上而柔下-雷风相与-巽而动-刚柔皆应-恒亨无咎-利贞。久于其道也。天地之道-恒久而不已也。利有攸往-终则有始也。日月得天而能久照-四时变化而能久成。圣人久于其道而天下化成。观其所恒-而天地万物之情可见矣。" tabindex="-1">彖曰：恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒亨无咎，利贞。久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成。圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣。 <a class="header-anchor" href="#彖曰-恒-久也。刚上而柔下-雷风相与-巽而动-刚柔皆应-恒亨无咎-利贞。久于其道也。天地之道-恒久而不已也。利有攸往-终则有始也。日月得天而能久照-四时变化而能久成。圣人久于其道而天下化成。观其所恒-而天地万物之情可见矣。" aria-label="Permalink to “彖曰：恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒亨无咎，利贞。久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成。圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣。”">​</a></h3><p>恒亨无咎，利贞，久于其道无不通也。行而可久，必无咎也。常久之利，利居贞也。</p><h3 id="象曰-雷风-恒。君子以立不易方。" tabindex="-1">象曰：雷风，恒。君子以立不易方。 <a class="header-anchor" href="#象曰-雷风-恒。君子以立不易方。" aria-label="Permalink to “象曰：雷风，恒。君子以立不易方。”">​</a></h3><h3 id="初六-浚恒-贞凶-无攸利-象曰-浚恒之凶-始求深也。" tabindex="-1">初六：浚恒，贞凶，无攸利 象曰：浚恒之凶，始求深也。 <a class="header-anchor" href="#初六-浚恒-贞凶-无攸利-象曰-浚恒之凶-始求深也。" aria-label="Permalink to “初六：浚恒，贞凶，无攸利 象曰：浚恒之凶，始求深也。”">​</a></h3><h3 id="九二-悔亡-象曰-九二悔亡-能久中也。" tabindex="-1">九二：悔亡 象曰：九二悔亡，能久中也。 <a class="header-anchor" href="#九二-悔亡-象曰-九二悔亡-能久中也。" aria-label="Permalink to “九二：悔亡 象曰：九二悔亡，能久中也。”">​</a></h3><h3 id="九三-不恒其德-或承之羞-贞吝-象曰-不恒其德-无所容也。" tabindex="-1">九三：不恒其德，或承之羞，贞吝 象曰：不恒其德，无所容也。 <a class="header-anchor" href="#九三-不恒其德-或承之羞-贞吝-象曰-不恒其德-无所容也。" aria-label="Permalink to “九三：不恒其德，或承之羞，贞吝 象曰：不恒其德，无所容也。”">​</a></h3><h3 id="九四-田无禽-象曰-久非其位-安得禽也。" tabindex="-1">九四：田无禽 象曰：久非其位，安得禽也。 <a class="header-anchor" href="#九四-田无禽-象曰-久非其位-安得禽也。" aria-label="Permalink to “九四：田无禽 象曰：久非其位，安得禽也。”">​</a></h3><h3 id="六五-恒其德-贞-妇人吉-夫子凶-象曰-妇人贞吉-从一而终也。夫子制义-从妇凶也。" tabindex="-1">六五：恒其德，贞，妇人吉，夫子凶 象曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。 <a class="header-anchor" href="#六五-恒其德-贞-妇人吉-夫子凶-象曰-妇人贞吉-从一而终也。夫子制义-从妇凶也。" aria-label="Permalink to “六五：恒其德，贞，妇人吉，夫子凶 象曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。”">​</a></h3><h3 id="上六-振恒-凶-象曰-振恒在上-大无功也。" tabindex="-1">上六：振恒，凶 象曰：振恒在上，大无功也。 <a class="header-anchor" href="#上六-振恒-凶-象曰-振恒在上-大无功也。" aria-label="Permalink to “上六：振恒，凶 象曰：振恒在上，大无功也。”">​</a></h3><p>振者，木之摇落也。上以柔弱之质，当恒久之终，体动而应风摇落之象也。常久之道，由兹而坠，故曰大无功也。</p>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
